import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate, useLocation } from 'react-router-dom';
import Home from './pages/Home';
import VideoDetail from './pages/VideoDetail';
import SavedNotes from './pages/SavedNotes';
import Login from './pages/Login';
import Profile from './pages/Profile';
import './App.css';

function Navbar({ searchTerm, setSearchTerm }) {
  const navigate = useNavigate();
  const location = useLocation();

  const handleSearch = (e) => {
    e.preventDefault();
    navigate('/home');
  };

  // Hide entire navbar elements on the Login screen if preferred, or keep logo/navigation active
  const isLoginPage = location.pathname === '/';

  return (
    <header className="navbar">
      <Link to="/home" className="logo-container">
        <svg
          className="logo-icon"
          width="32"
          height="32"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M12 2L2 7L12 12L22 7L12 2Z"
            stroke="#007bff"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M2 17L12 22L22 17"
            stroke="#007bff"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M2 12L12 17L22 12"
            stroke="#007bff"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
        <span className="logo-text">LearnStream</span>
      </Link>
      
      {/* Search bar displayed ONLY on Home page */}
      {location.pathname === '/home' && (
        <form onSubmit={handleSearch} className="nav-search">
          <input
            type="text"
            placeholder="Search lessons..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <button type="submit">Search</button>
        </form>
      )}

      {/* Right side navigation links */}
      {!isLoginPage && (
        <div className="nav-right">
          <Link to="/notes" className="nav-link">My Notes</Link>
          <Link to="/profile" className="profile-btn" title="Profile Settings">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
              <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
            </svg>
            <span>Profile</span>
          </Link>
        </div>
      )}
    </header>
  );
}

function App() {
  const [searchTerm, setSearchTerm] = useState('');

  return (
    <Router>
      <div className="app-container">
        <Navbar searchTerm={searchTerm} setSearchTerm={setSearchTerm} />
        <div className="main-content">
          <Routes>
            <Route path="/" element={<Login />} />
            <Route path="/home" element={<Home searchTerm={searchTerm} />} />
            <Route path="/video/:id" element={<VideoDetail />} />
            <Route path="/notes" element={<SavedNotes />} />
            <Route path="/profile" element={<Profile />} />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
